      h.setAttribute('data-prism-handle', dir);
      h.style.cssText = 'position:absolute;width:10px;height:10px;box-sizing:border-box;'
        + 'background:#fff;border:1.5px solid '+ACCENT+';border-radius:2px;display:none;'
